import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == n:
        all_binary = True
        for row in adj:
            if len(row) != n:
                all_binary = False
                break
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        degree = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    degree[i] += 1
    else:
        adj_list = adj
        degree = [len(adj_list[i]) for i in range(n)]

    # Trivial cases
    if all(d == 0 for d in degree):
        return [0] * n
    if all(d == n - 1 for d in degree):
        return list(range(n))

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if n > 0 else 0

    # Lower bound: size of maximum clique via iterative removal heuristic
    def clique_lower_bound():
        remaining = set(range(n))
        deg_copy = degree[:]
        clique_size = 0
        while remaining:
            v = max(remaining, key=lambda x: deg_copy[x])
            clique_size += 1
            to_remove = {v}
            for u in list(remaining):
                if u not in adj_list[v]:
                    to_remove.add(u)
            remaining -= to_remove
            for u in to_remove:
                if u in remaining:
                    deg_copy[u] = -1
        return clique_size

    lower_bound = clique_lower_bound()

    # DSATUR with efficient saturation updates and tie-breaking
    def dsatur():
        color = [-1] * n
        sat_sets = [set() for _ in range(n)]
        saturation = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            if not uncolored:
                break
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat_u = saturation[u]
                deg_u = 0
                for w in adj_list[u]:
                    if w in uncolored:
                        deg_u += 1
                if sat_u > max_sat or (sat_u == max_sat and deg_u > max_deg) or \
                   (sat_u == max_sat and deg_u == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat_u
                    max_deg = deg_u
                    v = u
            used = sat_sets[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    if c not in sat_sets[u]:
                        sat_sets[u].add(c)
                        saturation[u] += 1
        return color

    # RLF (Recursive Largest First) with optimized independent set growth
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            deg_uncolored = [0] * n
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg_uncolored[u] += 1
            start = max(uncolored, key=lambda u: deg_uncolored[u])
            S = {start}
            U = uncolored - {start} - set(adj_list[start])
            W = set(adj_list[start]) & uncolored
            while U:
                best_u = -1
                max_common = -1
                min_deg_U = float('inf')
                for u in U:
                    common = 0
                    for v in adj_list[u]:
                        if v in W:
                            common += 1
                    deg_u = 0
                    for v in adj_list[u]:
                        if v in U:
                            deg_u += 1
                    if common > max_common or \
                       (common == max_common and deg_u < min_deg_U) or \
                       (common == max_common and deg_u == min_deg_U and (best_u == -1 or random.random() < 0.5)):
                        max_common = common
                        min_deg_U = deg_u
                        best_u = u
                if best_u == -1:
                    break
                S.add(best_u)
                U.remove(best_u)
                for v in adj_list[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            for u in S:
                color[u] = c
            uncolored -= S
            c += 1
        return color

    # Kempe chain refinement for color class elimination (optimized)
    def kempe_refine(coloring, k):
        if k <= 1:
            return coloring
        improved = True
        while improved and k > 1:
            improved = False
            last_color = k - 1
            vertices_last = [v for v in range(n) if coloring[v] == last_color]
            if not vertices_last:
                k -= 1
                continue
            for v in vertices_last:
                # Try direct move to a lower color
                moved = False
                for c in range(last_color):
                    conflict = False
                    for u in adj_list[v]:
                        if coloring[u] == c:
                            conflict = True
                            break
                    if not conflict:
                        coloring[v] = c
                        moved = True
                        improved = True
                        break
                if moved:
                    continue
                # Try Kempe chain swap
                for c in range(last_color):
                    stack = [v]
                    visited = set([v])
                    component = []
                    while stack:
                        node = stack.pop()
                        component.append(node)
                        for nb in adj_list[node]:
                            if nb not in visited and (coloring[nb] == c or coloring[nb] == last_color):
                                visited.add(nb)
                                stack.append(nb)
                    # Check if swap is safe: no neighbor of v gets color c after swap
                    safe = True
                    for u in adj_list[v]:
                        if coloring[u] == c and u not in component:
                            safe = False
                            break
                        if coloring[u] == last_color and u in component:
                            safe = False
                            break
                    if safe:
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = last_color
                            else:
                                coloring[node] = c
                        improved = True
                        break
                if improved:
                    break
        return coloring

    # Welsh-Powell ordering (degree descending)
    def welsh_powell():
        order_wp = sorted(range(n), key=lambda v: degree[v], reverse=True)
        return greedy_color(order_wp)

    # Smallest-Last (degeneracy ordering) with greedy coloring
    def smallest_last():
        order = []
        remaining = set(range(n))
        deg = degree[:]
        buckets = [[] for _ in range(n)]
        for v in range(n):
            buckets[deg[v]].append(v)
        ptr = 0
        for _ in range(n):
            while ptr < n and not buckets[ptr]:
                ptr += 1
            if ptr >= n:
                break
            v = buckets[ptr].pop()
            order.append(v)
            for u in adj_list[v]:
                if u in remaining:
                    old_deg = deg[u]
                    buckets[old_deg].remove(u)
                    deg[u] -= 1
                    new_deg = deg[u]
                    buckets[new_deg].append(u)
                    if new_deg < ptr:
                        ptr = new_deg
            remaining.remove(v)
        return greedy_color(order[::-1])

    # Hybrid heuristic: DSATUR with RLF-inspired restarts and adaptive tie-breaking
    def adaptive_dsatur_rlf():
        best_color_local = None
        best_k_local = float('inf')
        # Run DSATUR multiple times with different tie-breaking seeds
        for seed in range(5):  # Limited restarts for speed
            random.seed(seed)
            color_arr = dsatur()
            k = num_colors(color_arr)
            if k < best_k_local:
                best_k_local = k
                best_color_local = color_arr[:]
                if best_k_local == lower_bound:
                    break
        # If not optimal, try RLF as a diversifying strategy
        if best_k_local > lower_bound:
            color_rlf = rlf()
            k_rlf = num_colors(color_rlf)
            if k_rlf < best_k_local:
                best_k_local = k_rlf
                best_color_local = color_rlf[:]
        return best_color_local

    # Run core algorithms and pick the best
    algorithms = [
        ("Adaptive DSATUR/RLF", adaptive_dsatur_rlf),
        ("Welsh-Powell", welsh_powell),
        ("Smallest-Last", smallest_last)
    ]
    best_color = None
    best_k = float('inf')
    for name, algo in algorithms:
        try:
            color_arr = algo()
            k = num_colors(color_arr)
            if k < best_k:
                best_k = k
                best_color = color_arr[:]
                if best_k == lower_bound:
                    break
        except Exception:
            continue

    # Apply Kempe refinement to the best solution
    if best_color is not None:
        refined_color = kempe_refine(best_color[:], best_k)
        refined_k = num_colors(refined_color)
        if refined_k < best_k:
            best_color = refined_color
            best_k = refined_k
            if best_k == lower_bound:
                return best_color

    # Fallback: Welsh-Powell (should not be needed, but safe)
    if best_color is None:
        best_color = welsh_powell()

    return best_color

