import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []

    # Detect adjacency matrix: square and binary entries (0 or 1)
    is_matrix = (
        n > 0
        and len(adj[0]) == n
        and all(
            isinstance(row, list)
            and len(row) == n
            and all(x in (0, 1) for x in row)
            for row in adj
        )
    )
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1 and i != j:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
        return color

    # Helper: Welsh-Powell ordering (descending degree)
    def welsh_powell_order():
        return sorted(range(n), key=lambda v: len(adj_list[v]), reverse=True)

    # Helper: DSATUR ordering with tie-breaking by degree in uncolored subgraph
    def dsatur_order():
        color = [-1] * n
        sat = [0] * n
        uncolored_deg = [len(adj_list[v]) for v in range(n)]
        uncolored = set(range(n))
        order = []
        for _ in range(n):
            v = max(
                uncolored,
                key=lambda x: (sat[x], uncolored_deg[x], -x)
            )
            order.append(v)
            uncolored.remove(v)
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            for u in adj_list[v]:
                if u in uncolored:
                    new_sat = True
                    for w in adj_list[u]:
                        if color[w] == color[v]:
                            new_sat = False
                            break
                    if new_sat:
                        sat[u] += 1
                    uncolored_deg[u] -= 1
        return order

    # Helper: Smallest-Last (SL) ordering (Matula & Beck, 1983)
    def smallest_last_order():
        deg = [len(adj_list[v]) for v in range(n)]
        max_deg = max(deg) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = deg[v]
            if d < len(buckets):
                buckets[d].add(v)
            else:
                while len(buckets) <= d:
                    buckets.append(set())
                buckets[d].add(v)

        order = []
        for _ in range(n):
            min_deg = 0
            while min_deg < len(buckets) and len(buckets[min_deg]) == 0:
                min_deg += 1
            if min_deg >= len(buckets):
                break
            v = buckets[min_deg].pop()
            order.append(v)
            for u in adj_list[v]:
                if u not in order:
                    d_u = deg[u]
                    if d_u < len(buckets) and u in buckets[d_u]:
                        buckets[d_u].remove(u)
                    deg[u] -= 1
                    new_d = deg[u]
                    if new_d < len(buckets):
                        buckets[new_d].add(u)
                    else:
                        while len(buckets) <= new_d:
                            buckets.append(set())
                        buckets[new_d].add(u)
        return order

    # Helper: RLF (Recursive Largest First) independent set extraction
    def rlf_color():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            S = []
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            S.append(v)
            U = {u for u in uncolored if u not in S and all(u not in adj_list[s] for s in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                u = max(
                    U,
                    key=lambda x: (
                        sum(1 for y in adj_list[x] if y in W),
                        -sum(1 for y in adj_list[x] if y in U),
                        -x
                    )
                )
                S.append(u)
                U.remove(u)
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            for v in S:
                color[v] = c
            uncolored -= set(S)
            c += 1
        return color

    # Helper: Saturation-guided independent set extraction (hybrid)
    def saturation_independent_set_color():
        color = [-1] * n
        uncolored = set(range(n))
        sat = [0] * n
        uncolored_deg = [len(adj_list[v]) for v in range(n)]
        c = 0
        while uncolored:
            S = []
            v = max(
                uncolored,
                key=lambda x: (sat[x], uncolored_deg[x], random.random())
            )
            S.append(v)
            U = {u for u in uncolored if u not in S and all(u not in adj_list[s] for s in S)}
            W = {u for u in uncolored if u not in S and u not in U}
            while U:
                u = max(
                    U,
                    key=lambda x: (
                        sum(1 for y in adj_list[x] if y in W),
                        -sum(1 for y in adj_list[x] if y in U),
                        sat[x],
                        random.random()
                    )
                )
                S.append(u)
                U.remove(u)
                for y in adj_list[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            for v in S:
                color[v] = c
            for v in S:
                for u in adj_list[v]:
                    if u in uncolored:
                        new_sat = True
                        for w in adj_list[u]:
                            if color[w] == c:
                                new_sat = False
                                break
                        if new_sat:
                            sat[u] += 1
                        uncolored_deg[u] -= 1
            uncolored -= set(S)
            c += 1
        return color

    # Try multiple heuristics and keep the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')

    # 1. Welsh-Powell
    wp_order = welsh_powell_order()
    wp_color = greedy_color(wp_order)
    wp_max = max(wp_color) if wp_color else -1
    if wp_max + 1 < best_num_colors:
        best_num_colors = wp_max + 1
        best_coloring = wp_color[:]

    # 2. DSATUR
    ds_order = dsatur_order()
    ds_color = greedy_color(ds_order)
    ds_max = max(ds_color) if ds_color else -1
    if ds_max + 1 < best_num_colors:
        best_num_colors = ds_max + 1
        best_coloring = ds_color[:]

    # 3. Smallest-Last ordering
    sl_order = smallest_last_order()
    sl_color = greedy_color(sl_order)
    sl_max = max(sl_color) if sl_color else -1
    if sl_max + 1 < best_num_colors:
        best_num_colors = sl_max + 1
        best_coloring = sl_color[:]

    # 4. RLF
    rlf_coloring = rlf_color()
    rlf_max = max(rlf_coloring) if rlf_coloring else -1
    if rlf_max + 1 < best_num_colors:
        best_num_colors = rlf_max + 1
        best_coloring = rlf_coloring[:]

    # 5. Saturation-guided independent set
    sat_is_color = saturation_independent_set_color()
    sat_is_max = max(sat_is_color) if sat_is_color else -1
    if sat_is_max + 1 < best_num_colors:
        best_num_colors = sat_is_max + 1
        best_coloring = sat_is_color[:]

    # 6. Randomized Welsh-Powell with shuffling ties
    for _ in range(15):
        order = sorted(range(n), key=lambda v: (len(adj_list[v]), random.random()), reverse=True)
        color = greedy_color(order)
        maxc = max(color) if color else -1
        if maxc + 1 < best_num_colors:
            best_num_colors = maxc + 1
            best_coloring = color[:]

    # 7. Randomized DSATUR with random tie-breaking
    for _ in range(15):
        color = [-1] * n
        sat = [0] * n
        uncolored_deg = [len(adj_list[v]) for v in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            v = max(
                uncolored,
                key=lambda x: (sat[x], uncolored_deg[x], random.random())
            )
            uncolored.remove(v)
            used = [False] * n
            for u in adj_list[v]:
                if color[u] != -1:
                    used[color[u]] = True
            c = 0
            while c < n and used[c]:
                c += 1
            color[v] = c
            for u in adj_list[v]:
                if u in uncolored:
                    new_sat = True
                    for w in adj_list[u]:
                        if color[w] == color[v]:
                            new_sat = False
                            break
                    if new_sat:
                        sat[u] += 1
                    uncolored_deg[u] -= 1
        maxc = max(color) if color else -1
        if maxc + 1 < best_num_colors:
            best_num_colors = maxc + 1
            best_coloring = color[:]

    # Final greedy pass on best ordering to ensure validity and possibly improve
    if best_coloring is not None:
        for _ in range(10):
            order = sorted(range(n), key=lambda v: (best_coloring[v], random.random()))
            refined = greedy_color(order)
            if max(refined) + 1 < best_num_colors:
                best_coloring = refined
                best_num_colors = max(refined) + 1
            order = sorted(range(n), key=lambda v: (-best_coloring[v], random.random()))
            refined = greedy_color(order)
            if max(refined) + 1 < best_num_colors:
                best_coloring = refined
                best_num_colors = max(refined) + 1

    return best_coloring
